<?php

declare(strict_types = 1);

namespace SineMacula\Laravel\Sso\Models;

use SineMacula\Laravel\Sso\Keys\Enums\KeyState;
use SineMacula\Laravel\Sso\Keys\Enums\KeyType;
use SineMacula\Laravel\Sso\Keys\Enums\KeyUse;
use SineMacula\Laravel\Sso\Models\Casts\UtcDateTime;

/**
 * One row of a connection's keys and certificates (SSO-2.6, SSO-2.7): a key
 * pair of the service provider's own, generated by the package with a
 * self-signed certificate and rotated through `next`, `current` and `retiring`,
 * or a signing certificate of the identity provider the connection trusts, one
 * of a set, with no private key and no state.
 *
 * It holds the use, the state, the key's type and size, the certificate and the
 * public key (PEM), the SHA-256 fingerprint (of the certificate's DER when
 * there is one, of the public key's otherwise, as `Secrets\MaskedKey` computes
 * it), the certificate's validity (reported, never enforced), when the key was
 * made current, and until when a retiring key is still accepted for decryption.
 * A private key is stored only encrypted, through `Contracts\SecretEncrypter`,
 * and hidden from serialisation; a helper never returns it (SSO-2.5).
 *
 * Its key is a lower-case ULID and its timestamps come from the package's clock
 * (see `SsoModel`). The table comes from `sso.keys.table`, the connection from
 * the storage connection. Only the class name is public; its columns and
 * behaviour belong to the key operations.
 *
 * @api
 *
 * @author      Ben Carey <bdmc@sinemacula.co.uk>
 * @copyright   2026 Sine Macula Limited
 *
 * @property string $id
 * @property string $connection_id
 * @property \SineMacula\Laravel\Sso\Keys\Enums\KeyUse $use
 * @property ?\SineMacula\Laravel\Sso\Keys\Enums\KeyState $state
 * @property \SineMacula\Laravel\Sso\Keys\Enums\KeyType $key_type
 * @property int $key_bits
 * @property ?string $certificate
 * @property string $public_key
 * @property ?string $private_key
 * @property string $fingerprint
 * @property ?\Carbon\CarbonImmutable $not_before
 * @property ?\Carbon\CarbonImmutable $not_after
 * @property ?\Carbon\CarbonImmutable $made_current_at
 * @property ?\Carbon\CarbonImmutable $retiring_until
 * @property \Carbon\CarbonImmutable $created_at
 * @property \Carbon\CarbonImmutable $updated_at
 */
final class ConnectionKey extends SsoModel
{
    /** @var string The key, under `sso.`, of the setting that names the model's table. */
    protected const string TABLE = 'keys.table';

    /** @var bool Indicates if the IDs are auto-incrementing. */
    public $incrementing = false;

    /** @var bool Indicates if the model should be timestamped: the package stamps it from its clock instead. */
    public $timestamps = false;

    /** @var string The "type" of the primary key ID. */
    protected $keyType = 'string';

    /** @var array<string> The attributes that aren't mass assignable. */
    protected $guarded = ['*'];

    /** @var list<string> The attributes hidden from serialisation: the encrypted private key. */
    protected $hidden = ['private_key'];

    /**
     * Key and stamp each new row.
     *
     * @return void
     */
    #[\Override]
    protected static function booted(): void
    {
        self::identifiedAndStamped();
    }

    /**
     * The attributes that should be cast.
     *
     * @return array<string, string>
     */
    #[\Override]
    protected function casts(): array
    {
        return [
            'use'             => KeyUse::class,
            'state'           => KeyState::class,
            'key_type'        => KeyType::class,
            'key_bits'        => 'integer',
            'not_before'      => UtcDateTime::class,
            'not_after'       => UtcDateTime::class,
            'made_current_at' => UtcDateTime::class,
            'retiring_until'  => UtcDateTime::class,
            'created_at'      => UtcDateTime::class,
            'updated_at'      => UtcDateTime::class,
        ];
    }
}
